CREATE TABLE `op_dispatch_rule` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `rule_code` varchar(64) NOT NULL,
  `rule_name` varchar(128) NOT NULL,
  `dispatch_dimension` varchar(30) DEFAULT NULL COMMENT '派单维度:TYPE/AMOUNT/LEGAL/COMPLEXITY/REGION',
  `match_condition` varchar(255) DEFAULT NULL COMMENT '匹配条件(按维度解释)',
  `task_type` varchar(32) DEFAULT NULL,
  `company_id` bigint DEFAULT NULL,
  `company_name` varchar(128) DEFAULT NULL,
  `expense_item_id` bigint DEFAULT NULL,
  `expense_item_name` varchar(128) DEFAULT NULL,
  `currency_code` varchar(16) DEFAULT NULL,
  `target_group_id` bigint DEFAULT NULL,
  `target_group_name` varchar(128) DEFAULT NULL,
  `mode` varchar(16) NOT NULL DEFAULT 'SYSTEM',
  `dispatch_strategy` varchar(30) DEFAULT 'ROUND_ROBIN' COMMENT '派单策略:ROUND_ROBIN/LOAD_BALANCE/SKILL_MATCH',
  `priority` int DEFAULT '5',
  `sla_hours` decimal(8,2) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'NORMAL',
  `remark` varchar(500) DEFAULT NULL,
  `create_by` bigint DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  `update_by` bigint DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `del_flag` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_tenant` (`tenant_id`),
  KEY `idx_group` (`target_group_id`)
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='抢派单规则';
